import { encryptionImmutable, invalidRequestBody } from "./problems.mjs";

// The server-side checks on an `encryption` descriptor of the `edv` scheme
// (PWS v0.5, Key Epochs: Server validation). The server never holds key
// material and never unwraps anything; it checks shapes, and across an
// update the invariants that protect a Collection's readers from a client
// bug: `epochs` is append-only, `currentEpoch` never moves backwards, the
// blinding key is permanent, and the scheme and wire-format version are
// set-once. The same checks run on the head `state` of a governing history
// log (history.mjs), where the descriptor is not written directly.

const isObject = (value) => typeof value === "object" && value !== null && !Array.isArray(value);
const nonEmptyString = (value) => typeof value === "string" && value.length > 0;

function validateRecipients(recipients, pointer) {
  if (!Array.isArray(recipients) || recipients.length === 0) {
    throw invalidRequestBody(`${pointer} must be a non-empty array of wrapped-key entries.`);
  }
  recipients.forEach((entry, i) => {
    const at = `${pointer}/${i}`;
    if (!isObject(entry) || !isObject(entry.header)) {
      throw invalidRequestBody(`${at} must carry a "header" object.`);
    }
    if (!nonEmptyString(entry.header.kid) || !nonEmptyString(entry.header.alg)) {
      throw invalidRequestBody(`${at}/header must carry non-empty "kid" and "alg" strings.`);
    }
    if (typeof entry.encrypted_key !== "string") {
      throw invalidRequestBody(`${at} must carry a string "encrypted_key".`);
    }
  });
}

// Shape validation of a descriptor a write supplies. `pointer` names the
// member in the request body for the problem's detail.
export function validateEncryptionDescriptor(descriptor, pointer = "/encryption") {
  if (!isObject(descriptor) || typeof descriptor.scheme !== "string") {
    throw invalidRequestBody(`${pointer} must be an object with a string "scheme".`);
  }
  if (descriptor.version !== undefined && !(Number.isInteger(descriptor.version) && descriptor.version > 0)) {
    throw invalidRequestBody(`${pointer}/version must be a positive integer.`);
  }
  if (descriptor.scheme !== "edv") {
    return;
  }
  const hasEpochs = descriptor.epochs !== undefined;
  const hasCurrent = descriptor.currentEpoch !== undefined;
  if (hasEpochs !== hasCurrent) {
    throw invalidRequestBody(`${pointer}: "epochs" and "currentEpoch" appear together or not at all.`);
  }
  if (hasEpochs) {
    if (!Array.isArray(descriptor.epochs) || descriptor.epochs.length === 0) {
      throw invalidRequestBody(`${pointer}/epochs must be a non-empty array.`);
    }
    const ids = new Set();
    descriptor.epochs.forEach((epoch, i) => {
      if (!isObject(epoch) || !nonEmptyString(epoch.id)) {
        throw invalidRequestBody(`${pointer}/epochs/${i} must carry a non-empty string "id".`);
      }
      if (ids.has(epoch.id)) {
        throw invalidRequestBody(`${pointer}/epochs/${i}: the epoch id "${epoch.id}" repeats.`);
      }
      ids.add(epoch.id);
      validateRecipients(epoch.recipients, `${pointer}/epochs/${i}/recipients`);
    });
    if (!nonEmptyString(descriptor.currentEpoch) || !ids.has(descriptor.currentEpoch)) {
      throw invalidRequestBody(`${pointer}/currentEpoch must name an epoch in "epochs".`);
    }
  }
  if (descriptor.hmac !== undefined) {
    if (!isObject(descriptor.hmac) || !nonEmptyString(descriptor.hmac.id) || !nonEmptyString(descriptor.hmac.type)) {
      throw invalidRequestBody(`${pointer}/hmac must be an object with non-empty "id" and "type" strings.`);
    }
    validateRecipients(descriptor.hmac.recipients, `${pointer}/hmac/recipients`);
  }
}

const epochIds = (descriptor) => new Set((descriptor.epochs ?? []).map((epoch) => epoch.id));

// The invariants across an update of a stored descriptor by a new one. A
// violation is the spec's encryption-immutable (409).
export function assertDescriptorTransition(stored, next) {
  if (!isObject(stored) || !isObject(next)) {
    return;
  }
  if (next.scheme !== stored.scheme) {
    throw encryptionImmutable(`The encryption scheme is set-once ("${stored.scheme}").`);
  }
  if ((next.version ?? 1) < (stored.version ?? 1)) {
    throw encryptionImmutable("The encryption version never decreases.");
  }
  if (stored.scheme !== "edv") {
    return;
  }
  // The epoch invariants are refused as a malformed write, as the reference
  // server refuses them; the set-once members below are the 409 kind
  const before = epochIds(stored);
  const after = epochIds(next);
  for (const id of before) {
    if (!after.has(id)) {
      throw invalidRequestBody(`/encryption/epochs is append-only: the epoch "${id}" cannot be dropped.`);
    }
  }
  if (stored.currentEpoch !== undefined && next.currentEpoch !== stored.currentEpoch && before.has(next.currentEpoch)) {
    throw invalidRequestBody(`/encryption/currentEpoch never moves backwards: "${next.currentEpoch}" is an earlier epoch.`);
  }
  if (isObject(stored.hmac)) {
    if (!isObject(next.hmac) || next.hmac.id !== stored.hmac.id || next.hmac.type !== stored.hmac.type) {
      throw encryptionImmutable('The blinding key ("hmac") is permanent: its id and type cannot change and it cannot be removed.');
    }
  }
}
